from pybricks.hubs import PrimeHub
from pybricks.parameters import Direction, Port, Stop
from pybricks.pupdevices import Motor
from pybricks.robotics import DriveBase

# Set up all devices.
prime_hub = PrimeHub()
rightmotor = Motor(Port.B, Direction.CLOCKWISE)
leftmotor = Motor(Port.A, Direction.COUNTERCLOCKWISE)
drive_base = DriveBase(rightmotor, leftmotor, 56, 114)
rightattachment = Motor(Port.D, Direction.CLOCKWISE)


# The main program starts here.
print('Hello, Pybricks!')
drive_base.straight(275)
drive_base.turn(-92)
drive_base.straight(320)
drive_base.turn(99)
rightattachment.run_angle(450, 115)
drive_base.straight(-93)
drive_base.turn(-90)
drive_base.straight(-350)
